import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { ArrowLeft, RefreshCw, AlertCircle, CheckCircle2, Wallet } from 'lucide-react';
import { adminApi } from '../api/admin';
import { useShop } from '../context/ShopContext';
import { CreditReconciliationReport } from '../types';

const AdminCreditReconciliation: React.FC = () => {
  const { formatPrice, shopConfig } = useShop();
  const [report, setReport] = useState<CreditReconciliationReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadReport = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await adminApi.getCreditReconciliation();
      setReport(data);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to load store credit reconciliation report.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadReport();
  }, [loadReport]);

  const currency = report?.currency || shopConfig.currency || 'IRR';
  const scalarMetrics = report
    ? Object.entries(report).filter(
        ([k, v]) =>
          k !== 'discrepancies' &&
          k !== 'summary' &&
          k !== 'generatedAt' &&
          k !== 'currency' &&
          (typeof v === 'number' || typeof v === 'string' || typeof v === 'boolean')
      )
    : [];

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pt-24 pb-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-[1360px] mx-auto space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-[#E4E4DE] dark:border-[#222630] pb-6">
          <div className="flex items-center gap-3">
            <Link
              to="/admin"
              className="p-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-slate-600 dark:text-slate-300 hover:border-slate-400"
            >
              <ArrowLeft size={16} />
            </Link>
            <div>
              <span className="text-xs font-mono font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                Finance &amp; Ledger Operations
              </span>
              <h1 className="text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight mt-0.5">
                Store Credit Reconciliation
              </h1>
            </div>
          </div>

          <button
            type="button"
            onClick={loadReport}
            disabled={loading}
            className="px-4 py-2 rounded-lg border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-xs font-semibold text-slate-700 dark:text-slate-200 hover:border-slate-400 inline-flex items-center gap-2 self-start sm:self-auto"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
            <span>Re-run Reconciliation</span>
          </button>
        </div>

        {error && (
          <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
            <AlertCircle size={15} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {loading ? (
          <div className="p-12 text-center bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl text-sm text-slate-500">
            Running store-credit ledger reconciliation...
          </div>
        ) : report ? (
          <div className="space-y-6">
            {/* Status Banner */}
            <div className="p-4 rounded-xl bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] flex flex-wrap items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 flex items-center justify-center">
                  <Wallet size={18} />
                </div>
                <div>
                  <div className="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">
                    <span>Ledger Parity Status</span>
                    {(report.discrepancyCount || 0) === 0 ? (
                      <span className="inline-flex items-center gap-1 text-xs font-semibold text-emerald-600 dark:text-emerald-400">
                        <CheckCircle2 size={14} /> Balanced
                      </span>
                    ) : (
                      <span className="text-xs font-semibold text-amber-600 dark:text-amber-400">
                        {report.discrepancyCount} Discrepancies Detected
                      </span>
                    )}
                  </div>
                  <div className="text-xs text-slate-500 dark:text-slate-400 font-mono">
                    Currency: {currency}
                    {report.generatedAt ? ` · Generated: ${new Date(report.generatedAt).toLocaleString()}` : ''}
                  </div>
                </div>
              </div>
            </div>

            {/* Summary KPI Cards */}
            {scalarMetrics.length > 0 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {scalarMetrics.map(([key, val]) => {
                  const isAmount =
                    typeof val === 'number' && !key.toLowerCase().includes('count') && !key.toLowerCase().includes('totalaccounts');
                  return (
                    <div
                      key={key}
                      className="p-5 bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-xl space-y-1"
                    >
                      <div className="text-xs font-medium text-slate-500 dark:text-slate-400 capitalize">
                        {key.replace(/([A-Z])/g, ' $1').trim()}
                      </div>
                      <div className="text-lg font-extrabold font-mono tabular-nums text-slate-900 dark:text-white">
                        {typeof val === 'number'
                          ? isAmount
                            ? formatPrice(val, currency)
                            : val.toLocaleString()
                          : String(val)}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            {/* Discrepancies Table */}
            {Array.isArray(report.discrepancies) && report.discrepancies.length > 0 && (
              <div className="bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl overflow-hidden">
                <div className="px-6 py-4 border-b border-[#E4E4DE] dark:border-[#222630]">
                  <h2 className="text-sm font-bold text-slate-900 dark:text-white">
                    Account Discrepancies
                  </h2>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="border-b border-[#E4E4DE] dark:border-[#222630] bg-[#FBFBF9] dark:bg-[#161922] text-[11px] font-bold uppercase tracking-wider text-slate-500">
                        <th className="py-3 px-4">User ID</th>
                        <th className="py-3 px-4 text-right">Expected Balance</th>
                        <th className="py-3 px-4 text-right">Actual Balance</th>
                        <th className="py-3 px-4 text-right">Delta</th>
                        <th className="py-3 px-4">Reason</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[#E4E4DE] dark:divide-[#222630] text-xs">
                      {report.discrepancies.map((d, idx) => (
                        <tr key={d.userId || idx}>
                          <td className="py-3 px-4 font-mono">{d.userId || '—'}</td>
                          <td className="py-3 px-4 text-right font-mono tabular-nums">
                            {formatPrice(Number(d.expectedBalance) || 0, currency)}
                          </td>
                          <td className="py-3 px-4 text-right font-mono tabular-nums">
                            {formatPrice(Number(d.actualBalance) || 0, currency)}
                          </td>
                          <td className="py-3 px-4 text-right font-mono tabular-nums font-bold text-rose-500">
                            {formatPrice(Number(d.delta) || 0, currency)}
                          </td>
                          <td className="py-3 px-4 text-slate-500">{d.reason || '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {/* Extra Summary Breakdown if returned */}
            {report.summary && Object.keys(report.summary).length > 0 && (
              <div className="bg-white dark:bg-[#111318] border border-[#E4E4DE] dark:border-[#222630] rounded-2xl p-6 space-y-3">
                <h2 className="text-sm font-bold text-slate-900 dark:text-white">Ledger Summary</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 text-xs">
                  {Object.entries(report.summary).map(([k, v]) => (
                    <div key={k} className="p-3 rounded-lg bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between gap-2">
                      <span className="text-slate-500 dark:text-slate-400">{k}</span>
                      <span className="font-mono font-bold text-slate-900 dark:text-white">
                        {typeof v === 'number' ? v.toLocaleString() : JSON.stringify(v)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default AdminCreditReconciliation;
